  function showActionFeedback(){const f=state.actionFeedback;if(!f)return;$('#action-result-title').textContent=f.title;$('#action-result-outcome').textContent=f.outcome;$('#action-result-body').innerHTML=`<div class="action-result-deltas">${f.rows.map(row=>`<div title="${row.before.toFixed(2)} → ${row.after.toFixed(2)}"><span>${row.label}</span><strong class="${(row.key==='studentAnger'?row.delta<0:row.delta>0)?'plus':'minus'}">${row.key==='money'?(row.delta<0?'−':'+')+fmtMoney(Math.abs(row.delta)):signed(row.delta)}${row.key==='salaryPolicy'?'%':''}</strong></div>`).join('')||'<p>已执行，无即时数值变化。</p>'}</div>${f.notes.map(note=>`<p>${note}</p>`).join('')}${f.destination==='market'?'<button class="btn btn-secondary" id="feedback-market">查看新人才名单</button>':''}`;$('#action-result-close').onclick=()=>{state.actionFeedback=null;$('#action-result-modal').hidden=true;save();resumePendingFlow()};$('#feedback-market')?.addEventListener('click',()=>{state.actionFeedback=null;$('#action-result-modal').hidden=true;peopleTab='market';save();showView('people');resumePendingFlow()});$('#action-result-modal').hidden=false}
