  function renderCalendar(){if(!state)return;const now=getDate(),cursor=new Date(now.getFullYear(),now.getMonth()+calendarOffset,1),year=cursor.getFullYear(),month=cursor.getMonth(),first=(cursor.getDay()+6)%7,days=new Date(year,month+1,0).getDate(),items=calendarItems();$('#calendar-title').textContent=`${year} 年 ${month+1} 月`;let html='';for(let i=0;i<first;i++)html+='<div class="calendar-day outside" aria-hidden="true"></div>';for(let day=1;day<=days;day++){const date=isoDay(new Date(year,month,day)),dayItems=items.filter(x=>x.date===date),today=date===isoDay(now);html+=`<div class="calendar-day ${today?'today':''}"><b>${day}</b><div class="calendar-events">${dayItems.slice(0,3).map(x=>`<span class="calendar-event ${x.type} ${x.status||''}" title="${x.title}"><i></i>${x.title}</span>`).join('')}${dayItems.length>3?`<small>另 ${dayItems.length-3} 项</small>`:''}</div></div>`}$('#calendar-grid').innerHTML=html}
