  function openJointExamPlanner(targetId,editing=false){if(!editing)editingExamId=null;if(!editing&&state.money<35000)return toast('预约联考至少需要 ¥35,000。');if(!editing&&state.actionPoints<1)return toast('本周行动点不足。');examTargetId=targetId;const target=school(targetId),min=new Date(getDate());min.setDate(min.getDate()+(editing?1:3));const max=new Date(getDate());max.setDate(max.getDate()+60);$('#exam-modal-title').textContent=`与${target.name}制定联考方案`;$('#exam-target-note').textContent=editing?'调整已预约的日期和阵容，不重复收费。':'胜方加分，负方不扣分；可选择年级、班级与带队教师。';const date=$('#joint-exam-date');date.min=isoDay(min);date.max=isoDay(max);date.value=isoDay(min);const teachers=state.staffIds.map(staffById).filter(t=>t&&!state.exchangeTrips.some(x=>x.staffId===t.id&&x.status==='away')).sort((a,b)=>(b.stats[0]+b.stats[2]+b.stats[3])-(a.stats[0]+a.stats[2]+a.stats[3]));$('#joint-exam-teacher').innerHTML=teachers.map(t=>`<option value="${t.id}">${t.name} · ${t.subject} · 带队 ${teacherCommand(t).toFixed(2)}</option>`).join('');$$('[data-exam-grade]').forEach((b,i)=>b.checked=i===0);renderExamClassPickers();$('#exam-modal').hidden=false;date.onchange=renderExamPlanSummary;$('#joint-exam-teacher').onchange=renderExamPlanSummary;$$('[data-exam-grade]').forEach(b=>b.onchange=renderExamClassPickers)}
