    const labels={staffSatisfaction:'职工',teacherSatisfaction:'教师',studentSatisfaction:'学生'};Object.keys(state.lowSatisfactionMonths).forEach(key=>{state.lowSatisfactionMonths[key]=state[key]<10?state.lowSatisfactionMonths[key]+1:0;if(state.lowSatisfactionMonths[key]>=3)failGame(`${labels[key]}满意度连续 3 个月低于 10，爆发“${labels[key]}抗议”，你被撤销校长职务。`)});clampStats();checkFailureConditions()
