  function aiWeeklyTurn(){const rivals=state.schools.filter(s=>s.id!=='qiu');rivals.forEach(s=>{s.power=SchoolRules.clamp(s.power+(Math.random()-.4)*.3,25,99);s.exam=SchoolRules.clamp(s.exam+(Math.random()-.4)*.6,400,730);state.aiLog.unshift({date:isoDay(getDate()),school:s.id,action:'教学与人才培养'})});state.aiLog=state.aiLog.slice(0,40);if(!isGaokaoSeason())simulateRivalExam(rivals);state.inviteWaitWeeks=(state.inviteWaitWeeks||0)+1;const pool=rivals.filter(s=>!state.scheduledEvents.some(e=>e.targetId===s.id&&e.status==='scheduled'));if(pool.length&&(state.inviteWaitWeeks>=6||Math.random()<.35)){state.inviteWaitWeeks=0;return makeAIInvite(pool[Math.floor(Math.random()*pool.length)])}return null}

  function simulateRivalExam(rivals){if(rivals.length<2)return;const shuffled=[...rivals].sort(()=>Math.random()-.5);for(let i=0;i+1<shuffled.length;i+=2){const a=shuffled[i],b=shuffled[i+1],scoreA=SchoolRules.softScore(a.exam+35+(a.power-50)*.35+(Math.random()-.5)*20),scoreB=SchoolRules.softScore(b.exam+35+(b.power-50)*.35+(Math.random()-.5)*20),record=SchoolRules.settlePair(state,`rival-${state.day}-${a.id}-${b.id}`,a.id,b.id,scoreA,scoreB,isoDay(getDate()));state.rivalExamHistory??=[];state.rivalExamHistory.unshift(record);state.rivalExamHistory=state.rivalExamHistory.slice(0,30)}}

  function makeAIInvite(target){return{id:`invite-${state.day}-${target.id}`,kind:'aiInvite',targetId:target.id,tag:'校际来函',title:`${target.name}发来联考邀请`,text:`${target.name}来函提议七天后举行高二年级联合考试，考务组织费用由对方承担。教务处提醒，五个班的教学安排和带队教师都需要提前协调，成绩也将影响两校的较量。若日期与高考季冲突，考试会顺延至 6 月 11 日；对方希望学校尽快答复。`,choices:[{text:'接受邀请，组织高二参赛',hint:'七天后联考；校际关系 +4；无需支付预约费',effect:{}},{text:'协商延期，本次不参加',hint:'校长权威 −1；校际关系 −2',effect:{}},{text:'明确拒绝邀请',hint:'校长权威 −2；校际关系 −5',effect:{}}]}}
  function showEventFeedback(){const f=state.eventFeedback;if(!f)return;$('#event-tag').textContent='批示反馈';$('#event-title').textContent=f.title;$('#event-date').textContent=fmtDate(state.date);$('#event-icon').textContent='回';$('#event-text').textContent=f.story;$('.event-prompt').textContent='实际变化';$('#event-choices').replaceChildren();const details=document.createElement('p');details.textContent=f.changes;$('#event-choices').append(details);if(f.followup){const note=document.createElement('p');note.textContent='待跟进：相关事项已记入后续清单，最早一周后进入简报。';$('#event-choices').append(note)}const button=document.createElement('button');button.className='btn btn-primary';button.textContent=state.weeklyBrief?'返回工作简报':'完成';button.addEventListener('click',()=>{state.eventFeedback=null;save();window.CampusUI.render(state,{advice:secretaryAdviceCandidates()});$('#event-modal').hidden=true;resumePendingFlow()});$('#event-choices').append(button);$('#event-modal').hidden=false}
  function showWorkBrief(){const brief=state.weeklyBrief;if(!brief){resumePendingFlow();return}$('.event-prompt').textContent='校长批示';const remaining=brief.items.filter(x=>!x.done);if(!remaining.length){const invite=brief.invite;GameFlow.finishBrief(state);if(invite)state.pendingCampusEvent=invite;save();$('#event-modal').hidden=true;window.CampusUI.render(state,{advice:secretaryAdviceCandidates()});resumePendingFlow();return}$('#event-tag').textContent='每周工作简报';$('#event-title').textContent=`第${brief.week??Math.floor(brief.day/7)}周 · 三项校务`;$('#event-date').textContent=fmtDate(state.date);$('#event-icon').textContent='报';$('#event-text').textContent=`已处理 ${brief.items.length-remaining.length} / ${brief.items.length}`;$('#event-choices').innerHTML=brief.items.map((item,i)=>{const e=item.event||window.CampusEvents.find(item.id,D.events);return`<button class="event-choice" data-brief="${i}" ${item.done||!e?'disabled':''}><span>${String(i+1).padStart(2,'0')}</span><div><b>${e?.title||'事件不可用'}</b><small>${e?window.CampusEvents.eventType(e)+' · '+e.tag:''} · ${item.done?'已处理':'待处理'}</small></div><em>›</em></button>`}).join('');$('#event-modal').hidden=false;$$('[data-brief]').forEach(b=>b.onclick=()=>{const item=brief.items[Number(b.dataset.brief)],e=item.event||window.CampusEvents.find(item.id,D.events);if(e&&!item.done)showEvent(e)})}

  function showEvent(ev){if(ev.id==='openclass')ev={...ev,choices:[...ev.choices,{text:'暂缓安排',hint:'暂无额外影响',effect:{}}]};$('#event-tag').textContent=window.CampusEvents.eventType(ev)+' · '+ev.tag+(ev.kind==='crisis'?' · 突发风险':ev.kind==='state'?' · 状态触发':ev.kind==='opportunity'?' · 发展机会':'');$('#event-title').textContent=ev.title;$('#event-date').textContent=fmtDate(state.date);$('#event-icon').textContent=ev.kind==='aiInvite'?'函':ev.tag.slice(0,1);$('#event-text').textContent=ev.text;$('#event-choices').innerHTML=ev.choices.map((c,i)=>{const e=c.effect||{},reason=(e.money||0)<0&&state.money< -e.money?'资金不足':(e.ap||0)<0&&state.actionPoints< -e.ap?'行动点不足':'';return `<button class="event-choice" data-choice="${i}" ${reason?'disabled':''}><span>${String(i+1).padStart(2,'0')}</span><div><b>${c.text}</b><small>${(e.money||0)<0?'需资金 '+fmtMoney(-e.money):''}${reason?' · '+reason:''}</small></div><em>›</em></button>`}).join('');if(state.weeklyBrief){$('#event-choices').insertAdjacentHTML('beforeend','<button class="event-choice" id="brief-back">返回工作简报</button>');$('#brief-back').addEventListener('click',showWorkBrief)}$('#event-modal').hidden=false;$$('[data-choice]').forEach(b=>b.addEventListener('click',()=>resolveEvent(ev,Number(b.dataset.choice))))}
  function eventStat(key){return key==='studentAnger'?averageAnger():key==='studentMindset'?state.students.reduce((sum,s)=>sum+s.stats[2],0)/Math.max(1,state.students.length):state[key]}
  function resolveEvent(ev,index){
    if(ev.kind==='aiInvite'){if(state.eventFeedback)return;const briefItem=state.weeklyBrief?.items.find(x=>x.id===ev.id&&!x.done);if(state.weeklyBrief&&!briefItem)return;const target=school(ev.targetId),beforeAuthority=state.authority,beforeRelation=target.relation;let message;if(index===0){const date=new Date(getDate());date.setDate(date.getDate()+7);if(isGaokaoSeason(date))date.setDate(11);const teachers=state.staffIds.map(staffById).filter(Boolean).sort((a,b)=>teacherCommand(b)-teacherCommand(a));if(!teachers.length)return toast('当前没有可负责联考的教师，请选择其他方案。');const exam={id:`ai-exam-${state.day}-${target.id}`,type:'jointExam',date:isoDay(date),targetId:target.id,classKeys:[1,2,3,4,5].map(c=>classKey(2,c)),teacherId:teachers[0].id,status:'scheduled',source:'aiInvite'};state.scheduledEvents.push(exam);target.relation=D.clamp(target.relation+4,0,100);message=`教务处已回复${target.name}，联考安排在 ${fmtDate(date)}，由${teachers[0].name}负责。`;addNews(`接受${target.name}邀请，联考日期定为 ${fmtDate(date)}。`)}else{const authorityLoss=index===1?1:2,relationLoss=index===1?2:5;state.authority-=authorityLoss;target.relation=D.clamp(target.relation-relationLoss,0,100);message=`办公室已向${target.name}${index===1?'说明暂不参加并提出协商':'回复本次不参加'}，教务处将不安排本次联考。`;addNews(`${index===1?'协商延期':'拒绝'}${target.name}联考邀请，校长权威下降 ${authorityLoss}。`)}state.pendingCampusEvent=null;if(briefItem)briefItem.done=true;addCalendarEvent('event',ev.title);clampStats();state.eventFeedback={title:ev.title,story:message,changes:`校长权威 ${state.authority-beforeAuthority>=0?'+':''}${state.authority-beforeAuthority}，${target.short}关系 ${target.relation-beforeRelation>=0?'+':''}${target.relation-beforeRelation}`,followup:false};save();renderAll();showEventFeedback();return}
    const choice=ev.choices[index];if(!choice)return;const beforeEvent={stability:state.stability,adminEfficiency:state.adminEfficiency,studentMindset:eventStat('studentMindset'),schoolMorale:state.schoolMorale,studentAnger:averageAnger(),money:state.money,teaching:state.teaching,academics:state.academics,studentSatisfaction:state.studentSatisfaction,teacherSatisfaction:state.teacherSatisfaction,staffSatisfaction:state.staffSatisfaction,authority:state.authority,prestige:state.prestige,actionPoints:state.actionPoints};const beforeRelations=state.schools.map(s=>s.relation);const e=choice.effect||{};if((e.money||0)<0&&state.money< -e.money)return toast('资金不足，请选择其他方案。');if((e.ap||0)<0&&state.actionPoints< -e.ap)return toast('行动点不足，请选择其他方案。');if(state.eventFeedback)return;if(state.weeklyBrief&&!state.weeklyBrief.items.some(x=>x.id===ev.id&&!x.done))return;window.CampusEvents.record(state,ev,index);window.CampusEventResults.apply(state,e,{ledger,label:ev.title});state.pendingCampusEvent=null;const briefItem=state.weeklyBrief?.items.find(x=>x.id===ev.id&&!x.done);if(briefItem)briefItem.done=true;addCalendarEvent('event',ev.title);addNews(`${ev.title}：你选择了“${choice.text}”。`);clampStats();recalculateAdministration();state.stability=stabilitySnapshot().value;const labels={stability:'稳定度',adminEfficiency:'行政效率',studentMindset:'平均心态',schoolMorale:'士气',studentAnger:'平均愤怒',stabilityBonus:'稳定修正',money:'资金',teaching:'教学',academics:'学业',studentSatisfaction:'学生满意',teacherSatisfaction:'教师满意',staffSatisfaction:'职工满意',safety:'稳定修正',stabilityBonus:'稳定修正',authority:'权威',prestige:'声望',actionPoints:'行动点',adminModifier:'管理修正'};const changes=Object.keys(beforeEvent).filter(k=>Math.abs(eventStat(k)-beforeEvent[k])>.001).map(k=>labels[k]+' '+(eventStat(k)-beforeEvent[k]>0?'+':'')+Number((eventStat(k)-beforeEvent[k]).toFixed(2)));if(e.relation)changes.push('校际关系：'+state.schools.map((s,i)=>`${s.short} ${signed(s.relation-beforeRelations[i])}`).join('、'));const branch=window.CampusEventLibrary.followups[ev.id+':'+index]||(index===0&&window.CampusEventLibrary.followups[ev.id]);state.eventFeedback={title:ev.title,story:choice.feedback||`校长决定“${choice.text}”后，相关人员接到了安排。负责人将本次批示记入工作记录，并把处理情况交回办公室。`,changes:changes.join('，')||'本次没有直接数值变化。',followup:!!branch};save();renderAll();showEventFeedback()
  }
  function finishGame(){state.gameOver=true;const rank=SchoolRules.rank(state);const grade=state.power>=82?'S':state.power>=70?'A':state.power>=60?'B':'C';save();setTimeout(()=>alert(`任期结束\n\n最终评价：${grade}\n全市排名：第 ${rank} 名\n综合实力：${Math.round(state.power)}\n学校声望：${Math.round(state.prestige)}\n\n你的决定已经成为秋秋一中校史的一部分。`),50)}

